// Pension Helper: checks EVERY pensioner of every signed-up workspace, each with its own DA rates.
const WS = Object.fromEntries($('Get workspaces').all().map(i => i.json).filter(w => w.key).map(w => [w.key, w]));
const active = r => !!r.dataset && r.dataset !== 'demo' && !!WS[r.dataset];
const daFor = ds => { const w = WS[ds] || {}; return { old: Number(w.da_old ?? 55), nu: Number(w.da_new ?? 58), from: w.da_new_from || '2026-07' }; };
const URGENT_DAYS = 7;

const zone = 'Asia/Kolkata';
const today = DateTime.now().setZone(zone).startOf('day');
const year = today.year;
const inr = (n) => '₹' + Math.round(n).toLocaleString('en-IN');
const monthLabel = (m) => DateTime.fromFormat(m, 'yyyy-MM').toFormat('LLLL yyyy');
const dayIn = v => v ? DateTime.fromISO(typeof v === 'string' ? v : new Date(v).toISOString()).setZone(zone).toISODate() : null;

const pensioners = $('Get all pensioners').all().map(i => i.json).filter(p => p.name && active(p));
const allPayments = $('Get all pension payments').all().map(i => i.json).filter(r => r.name && r.month && active(r));

return pensioners.map(p => {
  const DA = daFor(p.dataset);
  const openDate = DateTime.fromObject({ year, month: p.age >= 80 ? 10 : 11, day: 1 }, { zone });
  const deadline = DateTime.fromObject({ year, month: 11, day: 30 }, { zone });
  const daysLeft = Math.round(deadline.diff(today, 'days').days);
  const verifiedUntil = dayIn(p.lc_verified_until);
  const submitted = !!verifiedUntil && verifiedUntil > deadline.toISODate();
  let lcStatus;
  if (submitted) lcStatus = 'done';
  else if (today < openDate) lcStatus = 'not_open_yet';
  else if (daysLeft < 0) lcStatus = 'missed';
  else if (daysLeft <= URGENT_DAYS) lcStatus = 'urgent';
  else lcStatus = 'open';

  const months = allPayments
    .filter(r => r.name === p.name && r.dataset === p.dataset)
    .sort((a, b) => (a.month < b.month ? -1 : 1))
    .map(r => {
      const da = r.month >= DA.from ? DA.nu : DA.old;
      const expected = Math.round(r.basic_pension * (1 + da / 100) - (r.commuted_amount || 0));
      const received = Number(r.amount_received) || 0;
      const difference = expected - received;
      const status = received === 0 ? 'missing' : (difference > 0 ? 'short' : 'ok');
      return { month: r.month, expected, received, difference, status };
    });
  const problems = months.filter(m => m.status !== 'ok');
  const amountShort = problems.reduce((s, m) => s + m.difference, 0);
  const paymentStatus = months.length === 0 ? 'no_data' : (problems.length ? 'problem' : 'ok');
  const problemSummary = problems.map(m => m.status === 'missing'
    ? monthLabel(m.month) + ': nothing paid (' + inr(m.expected) + ' expected)'
    : monthLabel(m.month) + ': paid ' + inr(m.received) + ' instead of ' + inr(m.expected)).join('; ');
  const lcNeedsAction = ['open', 'urgent', 'missed'].includes(lcStatus);
  return { json: { name: p.name, bank: p.bank, dataset: p.dataset, lc_status: lcStatus, lc_days_left: daysLeft, payment_status: paymentStatus, problem_months: problems.length, amount_short: amountShort, problem_summary: problemSummary, issues_count: problems.length + (lcNeedsAction ? 1 : 0) } };
});
